/bin/zsh -lc "Rscript -e '
p <- \"/private/tmp/refine-review-20260914/paper_v4.Rmd\"
b <- \"reports/refine_ink_review_paper_v4_2026-09-14/execution/baseline/paper_v4.Rmd\"
parse_chunks <- function(path) {
  x <- readLines(path, warn = FALSE, encoding = \"UTF-8\")
  inside <- FALSE
  code <- character()
  labels <- character()
  parsed <- 0L
  for (ln in x) {
    if ("'!inside && startsWith(ln, "```{r")) {
      inside <- TRUE
      hdr <- substring(ln, 6L)
      lab <- sub("[,}].*$", "", hdr)
      labels <- c(labels, trimws(lab))
      code <- character()
    } else if (inside && grepl("''^```[[:space:]]*$", ln)) {
      parse(text = paste(code, collapse = "'"\\n\"), keep.source = TRUE)
      parsed <- parsed + 1L
      inside <- FALSE
    } else if (inside) {
      code <- c(code, ln)
    }
  }
  stopifnot("'!inside, !anyDuplicated(labels), all(nzchar(labels)))
  refs <- character()
  for (ln in x) {
    starts <- gregexpr("@ref(", ln, fixed = TRUE)[[1]]
    if (starts[1] > 0L) {
      for (s in starts) {
        tail <- substring(ln, s + 5L)
        close <- regexpr(")", tail, fixed = TRUE)[1]
        if (close > 0L) refs <- c(refs, substring(tail, 1L, close - 1L))
      }
    }
  }
  ref_labels <- sub("''^(fig|tab):", "", refs)
  missing <- setdiff(unique(ref_labels), labels)
  list(chunks = parsed, labels = labels, refs = refs, missing = missing)
}
extract_inline <- function(path) {
  x <- paste(readLines(path, warn = FALSE, encoding = "UTF-8"), collapse = "'"\\n\")
  unlist(regmatches(x, gregexpr(\""'`r[[:space:]]+[''^`]+`", x, perl = TRUE)), use.names = FALSE)
}
z <- parse_chunks(p)
zb <- parse_chunks(b)
stopifnot(length(z$missing) == 0L)
ia <- sort(extract_inline(p))
ib <- sort(extract_inline(b))
stopifnot(identical(ia, ib))
cat("PASS R chunk parse:", z$chunks, "chunks'"\\n\")
cat(\"PASS unique chunk labels:\", length(z"'$labels), "labels'"\\n\")
cat(\"PASS literal figure/table crossrefs:\", length(z"'$refs), "references; missing=0'"\\n\")
cat(\"PASS inline R expressions preserved:\", length(ia), \"expressions\\n\")
cat(\"Baseline chunks/labels:\", zb"'$chunks, length(zb$labels), "'"\\n\")
'"

